const t = new Date();
t.setDate(t.getDate() + 1);
const y = t.getFullYear();
const m = String(t.getMonth() + 1).padStart(2, '0');
const d = String(t.getDate()).padStart(2, '0');
return { timeMin: `${y}-${m}-${d}T00:00:00Z`, timeMax: `${y}-${m}-${d}T23:59:59Z` };

const eventos = $('Turnos de mañana').all();
const pacientes = $input.first().json;
let mensajes = [];
for (const e of eventos) {
  const summary = e.json.summary || '';
  const p = pacientes.find(p => p.nombre && summary.toLowerCase().includes(p.nombre.toLowerCase()));
  if (p && p.telefono) {
    const hora = new Date(e.json.start.dateTime).toLocaleTimeString('es-AR', {hour: '2-digit', minute:'2-digit'});
    mensajes.push({ telefono: p.telefono, mensaje: `¡Hola ${p.nombre}! 🏥 Te escribimos de Schbelta Clinic para confirmar tu turno de mañana a las *${hora}*. ¿Podemos contar con tu asistencia? Por favor responde SÍ o REPROGRAMAR.` });
  }
}
return mensajes;

const t = new Date();
t.setDate(t.getDate() - 1);
const y = t.getFullYear();
const m = String(t.getMonth() + 1).padStart(2, '0');
const d = String(t.getDate()).padStart(2, '0');
return { timeMin: `${y}-${m}-${d}T00:00:00Z`, timeMax: `${y}-${m}-${d}T23:59:59Z` };

const eventos = $('Turnos de Ayer').all();
const pacientes = $input.first().json;
let mensajes = [];
for (const e of eventos) {
  const summary = e.json.summary || '';
  const isCirugia = /extracci|implante|cirug|endodoncia|tratamiento/i.test(summary);
  if (!isCirugia) continue;
  const p = pacientes.find(p => p.nombre && summary.toLowerCase().includes(p.nombre.toLowerCase()));
  if (p && p.telefono) {
    mensajes.push({ telefono: p.telefono, mensaje: `¡Hola ${p.nombre}! 🏥 Te contactamos del equipo de Schbelta Clinic. ¿Cómo te sentís hoy tras la intervención de ayer? Del 1 al 10, ¿cuánto dolor o molestia sentís?` });
  }
}
return mensajes;

for (let item of $input.all()) {
  let base64String = item.json.body?.data?.message?.base64 || item.json.message?.base64 || item.json.base64;
  if (!base64String) throw new Error('❌ No se encontró el audio.');
  item.binary = { file: { data: base64String, mimeType: 'audio/ogg', fileName: 'audio.ogg' } };
}
return $input.all();

const webhookData = $('Webhook').first().json;
if (webhookData.body.event !== 'messages.upsert') return [];
let userMessage = '', phoneNumber = '', userName = 'Prospecto', isFromMe = false;
try {
  const messageData = webhookData.body.data;
  phoneNumber = (messageData.key.remoteJid || '').replace('@s.whatsapp.net', '');
  userName = messageData.pushName || 'Prospecto';
  isFromMe = messageData.key.fromMe || false;
  if ($input.first().json.text) {
    userMessage = $input.first().json.text;
  } else {
    const msg = messageData.message;
    if (msg?.conversation) userMessage = msg.conversation;
    else if (msg?.extendedTextMessage?.text) userMessage = msg.extendedTextMessage.text;
  }
} catch (e) { console.log('Error:', e); }
const fechaHoraHoy = new Date().toLocaleString('es-AR', { timeZone: 'America/Sao_Paulo', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
return { chatInput: userMessage, telefono: phoneNumber, nombreCliente: userName, isFromMe, fechaHoraHoy };

// ══════════════════════════════════════════
// GESTOR DE ESTADO — FIX: Bucle INFO resuelto
// ══════════════════════════════════════════
const prep = $('PREPARADOR DE DATOS').first().json;

let dbData = {};
try {
  const raw = $input.all();
  if (raw.length > 0 && raw[0].json) {
    const parsed = Array.isArray(raw[0].json) ? raw[0].json[0] : raw[0].json;
    if (parsed && (parsed.telefono || parsed.nombre)) dbData = parsed;
  }
} catch (e) { dbData = {}; }

let estadoActivo = false;
let necesidadActual = null;

if (dbData.estado_actual && dbData.ultima_actividad) {
  const minutosTranscurridos = (new Date() - new Date(dbData.ultima_actividad)) / 60000;

  // ✅ SOLUCIÓN AL BUCLE: Solo mantenemos el estado si es una transacción multi-paso
  const esEstadoTransaccional = ['AGENDAR', 'REAGENDAR', 'CANCELAR'].includes(dbData.estado_actual);

  if (minutosTranscurridos < 30 && esEstadoTransaccional) {
    estadoActivo = true;
    necesidadActual = dbData.estado_actual;
  }
}

return {
  estadoActivo,
  necesidad: necesidadActual,
  esNuevoPaciente: !dbData.nombre,
  is_pausada: dbData.is_pausada || false,
  chatInput: prep.chatInput || '',
  telefono: prep.telefono,
  nombreWhatsApp: prep.nombreCliente || 'Prospecto',
  fechaHoraHoy: prep.fechaHoraHoy,
  paciente_id: dbData.id || null,
  nombreEnDB: dbData.nombre || prep.nombreCliente || '',
  faseTratamiento: dbData.fase_tratamiento || 'Valoración',
  email: dbData.email || '',
  notasHistoricas: dbData.notas || '',
  calendarId: dbData.calendar_id || ''
};

