const rawContent = $input.first().json.choices[0].message.content;
let clasificacion;
try { clasificacion = JSON.parse(rawContent); } catch(e) { clasificacion = { necesidad: 'AGENDAR', urgencia: false, resumen: 'No clasificado' }; }
const ges = $('GESTOR DE ESTADO').first().json;
return { necesidad: clasificacion.necesidad || 'AGENDAR', urgencia: clasificacion.urgencia || false, resumenNecesidad: clasificacion.resumen || '', estadoActivo: false, chatInput: ges.chatInput, telefono: ges.telefono, nombreCliente: ges.nombreWhatsApp, fechaHoraHoy: ges.fechaHoraHoy, esNuevoPaciente: ges.esNuevoPaciente, nombreEnDB: ges.nombreEnDB, tratamientoActual: ges.faseTratamiento, calendarId: ges.calendarId, datosParciales: {} };

const ges = $('GESTOR DE ESTADO').first().json;
const base = { chatInput: ges.chatInput, telefono: ges.telefono, nombreCliente: ges.nombreWhatsApp || ges.nombreEnDB || 'Prospecto', fechaHoraHoy: ges.fechaHoraHoy, esNuevoPaciente: ges.esNuevoPaciente, nombreEnDB: ges.nombreEnDB, tratamientoActual: ges.faseTratamiento || 'Sin registro', calendarId: ges.calendarId || '', datosParciales: {} };
if (ges.estadoActivo === true) { return { ...base, necesidad: ges.necesidad, urgencia: false, resumenNecesidad: 'Continuando conversación anterior' }; }
const parser = $('PARSER CLASIFICADOR').first().json;
return { ...base, necesidad: parser.necesidad || 'AGENDAR', urgencia: parser.urgencia || false, resumenNecesidad: parser.resumenNecesidad || '' };

