const mensajeLimpio = agentOutput.replace(/\[GUARDAR_DATOS:\{.*?\}\]/, '').trim();
if (match) { let datos = {}; try { datos = JSON.parse(match[1]); } catch(e) {} return { output: mensajeLimpio, guardarEnSupabase: true, nombre: datos.nombre || $('PREPARADOR DE DATOS').first().json.nombreCliente, motivo: datos.motivo || '', preferencia: datos.preferencia || '', edad: datos.edad || '', calendarId: datos.calendarId || '', telefono: $('PREPARADOR DE DATOS').first().json.telefono }; } return { output: mensajeLimpio || agentOutput, guardarEnSupabase: false, telefono: $('PREPARADOR DE DATOS').first().json.telefono };

